import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}


def _parse_value(raw):
    value = raw.strip()
    if value[:1] in ("'", '"'):
        quote = value[0]
        end = value.find(quote, 1)
        # An unterminated quote takes the rest of the line.
        return value[1:] if end == -1 else value[1:end]
    # Unquoted: a " #" (or tab-#) starts an inline comment.
    for marker in (" #", "\t#"):
        cut = value.find(marker)
        if cut != -1:
            value = value[:cut]
    return value.strip()


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export ") or line.startswith("export\t"):
                line = line[len("export"):].lstrip()
            if "=" not in line:
                continue
            key, raw_value = line.split("=", 1)
            key = key.strip()
            if key:
                values[key] = _parse_value(raw_value)
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config

